import React, { useEffect, useState } from "react";
import { useParams, useNavigate, useLocation } from "react-router-dom";
import Sidebar from "../components/Sidebar";
import "../styles/Lesson.css";

export default function Lesson() {
  const { lessonId } = useParams();
  const navigate = useNavigate();
  const location = useLocation();
  const { lesson } = location.state || {};

  const [tutors, setTutors] = useState([]);
  const [sessions, setSessions] = useState([]);
  const [selectedTutor, setSelectedTutor] = useState(null);
  const [signupProcessing, setSignupProcessing] = useState(false);
  const [bookingStatus, setBookingStatus] = useState(null);
  const [bookedSession, setBookedSession] = useState(null);
  const [watchedVideos, setWatchedVideos] = useState({});
  const [currentVideoPlayer, setCurrentVideoPlayer] = useState(null);
  const [activeStep, setActiveStep] = useState(1);
  const [currentMonth, setCurrentMonth] = useState(new Date());
  const [selectedDate, setSelectedDate] = useState(null);

  // Videos for Lesson 1 (Biology)
  const lessonVideos = [
    { id: 1, title: "Introduction to Cells", url: "https://www.youtube.com/watch?v=tZE_fQFK8EY&list=PL8dPuuaLjXtPW_ofbxdHNciuLoTRLPMgB&index=2" },
    { id: 2, title: "Cell Structure", url: "https://www.youtube.com/watch?v=xOLcZMw0hd4&list=PL8dPuuaLjXtPW_ofbxdHNciuLoTRLPMgB&index=3" },
    { id: 3, title: "Photosynthesis", url: "https://www.youtube.com/watch?v=rgZhDoPgzK8&list=PL8dPuuaLjXtPW_ofbxdHNciuLoTRLPMgB&index=4" },
    { id: 4, title: "Cellular Respiration", url: "https://www.youtube.com/watch?v=cjR5zPrVjTc&list=PL8dPuuaLjXtPW_ofbxdHNciuLoTRLPMgB&index=5" },
    { id: 5, title: "DNA and Genetics", url: "https://www.youtube.com/watch?v=aO3Yp45zmw8&list=PL8dPuuaLjXtPW_ofbxdHNciuLoTRLPMgB&index=6" },
  ];

  const user = JSON.parse(localStorage.getItem("user")) || null;

  // Timeline steps for Lesson 1
  const timelineSteps = [
    { id: 1, title: "Watch 5 Videos", completed: Object.keys(watchedVideos).length === 5, current: Object.keys(watchedVideos).length < 5 },
    { id: 2, title: "Book a Tutor", completed: !!bookedSession, current: Object.keys(watchedVideos).length === 5 && !bookedSession },
    { id: 3, title: "Do 2 Worksheets", completed: false, current: false },
    { id: 4, title: "Q&A Post", completed: false, current: false },
    { id: 5, title: "Complete Game", completed: false, current: false },
    { id: 6, title: "Finish Lesson", completed: false, current: false },
  ];

  useEffect(() => {
    if (!lesson) {
      navigate("/");
      return;
    }

    async function loadLessonDetails() {
      try {
        // Fetch tutors
        const tRes = await fetch(`http://localhost:8080/lessons/${lessonId}/tutors`);
        const tData = await tRes.json();
        setTutors(tData.tutors || []);

        // Fetch sessions
        const sRes = await fetch(`http://localhost:8080/lessons/${lessonId}/sessions`);
        const sData = await sRes.json();
        const normalized = (sData.sessions || []).map((ss) => ({
          ...ss,
          spots_left: ss.max_spots - (ss.signed_up_count || ss.signed_up || 0),
        }));
        setSessions(normalized);
      } catch (err) {
        console.error("Failed to load lesson details:", err);
      }
    }

    loadLessonDetails();
  }, [lessonId, lesson, navigate]);

  function markVideoWatched(videoId) {
    setWatchedVideos((prev) => ({
      ...prev,
      [videoId]: true,
    }));
    setCurrentVideoPlayer(null);
  }

  function openVideoPlayer(video) {
    setCurrentVideoPlayer(video);
  }

  function closeVideoPlayer() {
    setCurrentVideoPlayer(null);
  }

  function handleStepClick(stepId) {
    // Allow clicking on completed steps or current step
    const step = timelineSteps.find(s => s.id === stepId);
    if (step && (step.completed || step.current)) {
      setActiveStep(stepId);
    }
  }

  // Calendar helper functions
  function getDaysInMonth(date) {
    return new Date(date.getFullYear(), date.getMonth() + 1, 0).getDate();
  }

  function getFirstDayOfMonth(date) {
    return new Date(date.getFullYear(), date.getMonth(), 1).getDay();
  }

  function hasSessionOnDate(date) {
    if (!selectedTutor) return false;
    const tutorSess = sessions.filter(s => s.tutor_id === selectedTutor.id || s.tutorId === selectedTutor.id);
    return tutorSess.some(session => {
      const sessionDate = new Date(session.session_time);
      return sessionDate.getDate() === date.getDate() &&
             sessionDate.getMonth() === date.getMonth() &&
             sessionDate.getFullYear() === date.getFullYear();
    });
  }

  function getSessionsForDate(date) {
    if (!selectedTutor) return [];
    const tutorSess = sessions.filter(s => s.tutor_id === selectedTutor.id || s.tutorId === selectedTutor.id);
    return tutorSess.filter(session => {
      const sessionDate = new Date(session.session_time);
      return sessionDate.getDate() === date.getDate() &&
             sessionDate.getMonth() === date.getMonth() &&
             sessionDate.getFullYear() === date.getFullYear();
    });
  }

  async function handleSignupToSession(session) {
    if (!user) {
      alert("Please log in to join a session");
      return;
    }

    if (session.spots_left === 0) {
      setBookingStatus({ type: "error", message: "This session is full" });
      return;
    }

    setSignupProcessing(true);
    try {
      const res = await fetch(`http://localhost:8080/sessions/${session.id}/signup`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          user_id: user.id,
          name: user.firstName,
          email: user.email,
        }),
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.message || "Signup failed");

      setBookedSession(session);
      setBookingStatus({ type: "success", message: "Successfully booked session!" });
      setSessions((prev) =>
        prev.map((p) =>
          p.id === session.id ? { ...p, spots_left: Math.max(0, (p.spots_left || p.max_spots) - 1) } : p
        )
      );

      // Update timeline - mark first step as completed
      timelineSteps[0].completed = true;
      timelineSteps[1].current = true;

      setTimeout(() => setBookingStatus(null), 3000);
    } catch (err) {
      console.error(err);
      setBookingStatus({ type: "error", message: err.message || "Booking failed" });
    } finally {
      setSignupProcessing(false);
    }
  }

  if (!lesson) {
    return (
      <div className="dashboard-page">
        <Sidebar />
        <main className="dashboard-main">
          <p>Loading...</p>
        </main>
      </div>
    );
  }

  // Check if this is Lesson 1
  const isLesson1 = lesson.lesson_number === 1;

  return (
    <div className="dashboard-page">
      <Sidebar />
      <main className="dashboard-main lesson-main">
        {/* Video Player Modal */}
        {currentVideoPlayer && (
          <div className="video-player-modal">
            <div className="video-player-backdrop" onClick={closeVideoPlayer} />
            <div className="video-player-container">
              <button className="video-player-close" onClick={closeVideoPlayer}>✕</button>
              <div className="video-player-content">
                <h2>{currentVideoPlayer.title}</h2>
                <div className="video-player-iframe">
                  <iframe
                    width="100%"
                    height="100%"
                    src={`https://www.youtube.com/embed/${currentVideoPlayer.url.split('v=')[1].split('&')[0]}?autoplay=1`}
                    title={currentVideoPlayer.title}
                    frameBorder="0"
                    allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
                    allowFullScreen
                  />
                </div>
                <div className="video-player-actions">
                  <button 
                    className="mark-complete-btn"
                    onClick={() => {
                      markVideoWatched(currentVideoPlayer.id);
                    }}
                  >
                    ✓ Mark Complete & Close
                  </button>
                  <button 
                    className="video-close-btn"
                    onClick={closeVideoPlayer}
                  >
                    Close Without Marking
                  </button>
                </div>
              </div>
            </div>
          </div>
        )}

        {/* Back button */}
        <button className="back-btn" onClick={() => navigate(-1)}>
          ← Back
        </button>

        {/* Header */}
        <header className="lesson-header">
          <div>
            <h1>Lesson {lesson.lesson_number}</h1>
            <p className="lesson-subtitle">{lesson.title}</p>
          </div>
        </header>

        {/* LESSON 1: Timeline Progress */}
        {isLesson1 && (
          <div className="lesson-timeline">
            <h3 className="timeline-title">Lesson Progress</h3>
            <div className="timeline-container">
              {timelineSteps.map((step, index) => {
                const isClickable = step.completed || step.current;
                return (
                  <div 
                    key={step.id} 
                    className="timeline-item"
                    onClick={() => handleStepClick(step.id)}
                    style={{ cursor: isClickable ? 'pointer' : 'not-allowed' }}
                  >
                    <div className={`timeline-step ${step.completed ? "completed" : step.current ? "current" : "pending"}`}>
                      {step.completed ? (
                        <svg width="20" height="20" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
                          <path d="M20 6L9 17l-5-5" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
                        </svg>
                      ) : (
                        <span>{step.id}</span>
                      )}
                    </div>
                    <div className="timeline-label">{step.title}</div>
                    {index < timelineSteps.length - 1 && <div className="timeline-connector" />}
                  </div>
                );
              })}
            </div>
          </div>
        )}

        {/* Booking status */}
        {bookingStatus && (
          <div className={`booking-alert booking-${bookingStatus.type}`}>
            {bookingStatus.message}
          </div>
        )}

        {/* Main content grid */}
        <div className="lesson-content-grid">
          {/* Left: Watch Videos Section (Step 1) - Show when activeStep === 1 */}
          {isLesson1 && activeStep === 1 && (
            <section className="lesson-section step-one-section">
              <div className="step-header">
                <div className="step-badge">Step 1</div>
                <h2>Watch 5 Videos</h2>
              </div>
              <p className="step-description">Complete all 5 videos to unlock the next step. Click "Watch" to start a video. Once finished, click "Mark Complete" to move to the next video.</p>

              <div className="videos-container">
                {lessonVideos.map((video) => (
                  <div key={video.id} className={`video-card ${watchedVideos[video.id] ? "watched" : ""}`} onClick={() => openVideoPlayer(video)} style={{ cursor: 'pointer' }}>
                    <div className="video-number">{video.id}</div>
                    <div className="video-content">
                      <h3>{video.title}</h3>
                      <p className="video-status">
                        {watchedVideos[video.id] ? "✓ Completed - Click to review" : `Video ${video.id} of 5`}
                      </p>
                    </div>
                    {!watchedVideos[video.id] ? (
                      <button 
                        className="video-btn"
                        onClick={(e) => {
                          e.stopPropagation();
                          openVideoPlayer(video);
                        }}
                      >
                        Watch →
                      </button>
                    ) : (
                      <div className="video-completed">✓</div>
                    )}
                  </div>
                ))}
              </div>
            </section>
          )}

          {/* Show Lesson Overview for non-Lesson1 pages */}
          {!isLesson1 && (
            <section className="lesson-section">
              <h2>Lesson Overview</h2>
              <div className="lesson-info-card">
                <p className="lesson-description">
                  {lesson.description || "Master the concepts and skills in this lesson with guided lessons and tutor support."}
                </p>
                <div className="lesson-meta">
                  <span className="meta-item">📚 Reading Time: 20 mins</span>
                  <span className="meta-item">🎓 Difficulty: Intermediate</span>
                </div>
              </div>

              {/* Video placeholder */}
              <div className="lesson-video-container">
                <div className="video-placeholder">
                  <svg width="64" height="64" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
                    <path d="M23 12a11 11 0 1 1-22 0 11 11 0 0 1 22 0z" stroke="#6366f1" strokeWidth="2"/>
                    <path d="M9.5 7.5v9l6.5-4.5-6.5-4.5z" fill="#6366f1"/>
                  </svg>
                  <p>Video content loading...</p>
                </div>
              </div>
            </section>
          )}

          {/* Tutors & Booking Section - Show when activeStep === 2 */}
          {isLesson1 && activeStep === 2 && (
            <section className="lesson-section tutors-section">
            <div className="step-header">
              <div className="step-badge">Step 2</div>
              <h2>Book a Tutor</h2>
            </div>
            <p className="step-description">You've completed Step 1! Now schedule a tutoring session with an expert tutor to discuss what you've learned.</p>
            {bookedSession && (
              <div className="booked-confirmation">
                <h3>✓ Session Booked</h3>
                <p className="booked-tutor">{selectedTutor?.name}</p>
                <p className="booked-time">{new Date(bookedSession.session_time).toLocaleString()}</p>
              </div>
            )}

            {tutors.length === 0 ? (
              <p className="muted">No tutors available for this lesson yet.</p>
            ) : (
              <div className="tutoring-container">
                {/* Tutors Selection */}
                <div className="tutors-list">
                  <h3>Select a Tutor</h3>
                  {tutors.map((tutor) => {
                    const tutorSess = sessions.filter(
                      (s) => s.tutor_id === tutor.id || s.tutorId === tutor.id
                    );
                    const isSelected = selectedTutor?.id === tutor.id;

                    return (
                      <div
                        key={tutor.id}
                        className={`tutor-card ${isSelected ? "selected" : ""}`}
                        onClick={() => setSelectedTutor(isSelected ? null : tutor)}
                      >
                        <div className="tutor-header">
                          <div className="tutor-avatar">{tutor.name.charAt(0).toUpperCase()}</div>
                          <div className="tutor-info">
                            <h3>{tutor.name}</h3>
                            <p className="tutor-bio">{tutor.bio || "Expert tutor"}</p>
                          </div>
                        </div>
                      </div>
                    );
                  })}
                </div>

                {/* Calendar View */}
                {selectedTutor && (
                  <div className="calendar-section">
                    <div className="calendar-header">
                      <button 
                        className="calendar-nav-btn"
                        onClick={() => setCurrentMonth(new Date(currentMonth.getFullYear(), currentMonth.getMonth() - 1))}
                      >
                        ← Prev
                      </button>
                      <h3>{currentMonth.toLocaleString('default', { month: 'long', year: 'numeric' })}</h3>
                      <button 
                        className="calendar-nav-btn"
                        onClick={() => setCurrentMonth(new Date(currentMonth.getFullYear(), currentMonth.getMonth() + 1))}
                      >
                        Next →
                      </button>
                    </div>

                    <div className="calendar-grid">
                      <div className="weekdays">
                        <div className="weekday">Sun</div>
                        <div className="weekday">Mon</div>
                        <div className="weekday">Tue</div>
                        <div className="weekday">Wed</div>
                        <div className="weekday">Thu</div>
                        <div className="weekday">Fri</div>
                        <div className="weekday">Sat</div>
                      </div>
                      <div className="days">
                        {Array(getFirstDayOfMonth(currentMonth)).fill(null).map((_, i) => (
                          <div key={`empty-${i}`} className="day empty"></div>
                        ))}
                        {Array(getDaysInMonth(currentMonth)).fill(null).map((_, i) => {
                          const date = new Date(currentMonth.getFullYear(), currentMonth.getMonth(), i + 1);
                          const hasSession = hasSessionOnDate(date);
                          const isToday = date.toDateString() === new Date().toDateString();
                          const isSelected = selectedDate?.toDateString() === date.toDateString();

                          return (
                            <div
                              key={i + 1}
                              className={`day ${hasSession ? "has-session" : ""} ${isToday ? "today" : ""} ${isSelected ? "selected" : ""}`}
                              onClick={() => hasSession && setSelectedDate(isSelected ? null : date)}
                              style={{ cursor: hasSession ? 'pointer' : 'default' }}
                            >
                              {i + 1}
                            </div>
                          );
                        })}
                      </div>
                    </div>

                    {/* Sessions for Selected Date */}
                    {selectedDate && (
                      <div className="sessions-for-date">
                        <h4>Available Sessions - {selectedDate.toLocaleDateString()}</h4>
                        {getSessionsForDate(selectedDate).length === 0 ? (
                          <p className="muted">No sessions on this date.</p>
                        ) : (
                          <div className="sessions-grid">
                            {getSessionsForDate(selectedDate).map((session) => (
                              <div key={session.id} className="session-card">
                                <div className="session-time">
                                  <strong>{new Date(session.session_time).toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit' })}</strong>
                                </div>
                                <div className="session-info">
                                  <span className="spots-badge">
                                    {session.spots_left > 0 ? `${session.spots_left} spots left` : "Full"}
                                  </span>
                                </div>
                                <button
                                  className="book-btn"
                                  disabled={signupProcessing || session.spots_left === 0 || bookedSession}
                                  onClick={(e) => {
                                    e.stopPropagation();
                                    handleSignupToSession(session);
                                  }}
                                >
                                  {signupProcessing ? "Booking..." : "Book Session"}
                                </button>
                              </div>
                            ))}
                          </div>
                        )}
                      </div>
                    )}
                  </div>
                )}
              </div>
            )}
          </section>
          )}
        </div>
      </main>
    </div>
  );
}
